# Problem 2
import itertools

def minutes(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

def fmt(m):
    h = (m // 60) % 12
    h = 12 if h == 0 else h
    return f"{h}:{m%60:02d}{'AM' if m < 12*60 else 'PM'}"

locs = ["North Beach","Mission District","The Castro"]
travel = {
    "North Beach": {"Mission District":18,"The Castro":22},
    "Mission District": {"North Beach":17,"The Castro":7},
    "The Castro": {"North Beach":20,"Mission District":7},
}
friends = [
    {"name":"James","loc":"Mission District","start":minutes("12:45"),"end":minutes("14:00"),"need":75},
    {"name":"Robert","loc":"The Castro","start":minutes("12:45"),"end":minutes("15:15"),"need":30},
]
start_loc = "North Beach"
start_time = minutes("9:00")

best = []
def dfs(cur_loc, cur_time, remaining, steps):
    global best
    if len(steps) > len(best):
        best = steps[:]
    for i, f in enumerate(remaining):
        tr = travel[cur_loc][f["loc"]]
        arrive = cur_time + tr
        meet_start = max(arrive, f["start"])
        if meet_start + f["need"] > f["end"]:
            continue
        new_steps = steps[:]
        if tr:
            new_steps.append(("travel", f["loc"], tr, arrive))
        if arrive < meet_start:
            new_steps.append(("wait", meet_start))
        new_steps.append(("meet", f["name"], meet_start, meet_start+f["need"]))
        dfs(f["loc"], meet_start+f["need"], remaining[:i]+remaining[i+1:], new_steps)

dfs(start_loc, start_time, friends, [])
out = [f'You start at {start_loc} at {fmt(start_time)}.']
for step in best:
    if step[0]=="travel":
        out.append(f'You travel to {step[1]} in {step[2]} minutes and arrive at {fmt(step[3])}.')
    elif step[0]=="wait":
        out.append(f'You wait until {fmt(step[1])}.')
    else:
        out.append(f'You meet {step[1]} from {fmt(step[2])} to {fmt(step[3])}.')
print(out)

